const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
const row = Array.isArray(body) ? body[0] : body;
if (status < 200 || status >= 300 || !row || !row.id) {
  throw new Error(`ICP Pack no encontrado o inaccesible (HTTP ${status || 'unknown'}).`);
}
if (row.status !== 'active') {
  throw new Error(`ICP Pack '${row.slug}' esta en estado '${row.status}', no 'active'. No se puede ejecutar un ICP que no esta activo (evita correr configuraciones en preparacion por accidente).`);
}
const init = $('Init ICP Config').first().json;
return [{json:{
  icp_pack_id: row.id,
  icp_pack_slug: row.slug,
  signals: row.signals || {},
  limit: init.limit,
  account_ids: init.account_ids
}}];

const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
if (status < 200 || status >= 300) throw new Error(`Supabase accounts read failed: HTTP ${status || 'unknown'}`);
const rows = Array.isArray(body) ? body : [];
if (!rows.length) return [{json:{_no_work:true, reason:'No accounts due for a signals check this run'}}];
return rows.map(a => ({json:{...a, _no_work:false}}));

const cfg = $('Init Configuration').first().json;
const account = $json;
const sigCfg = cfg.signals_config || {};
const types = Array.isArray(sigCfg.types) ? sigCfg.types : [];
const guidance = sigCfg.search_guidance || 'Busca eventos recientes y relevantes sobre esta cuenta.';

const system = `You are Prospector, the dedicated EnBandeja research agent. Follow your workspace AGENTS.md/SOUL.md rules. This run is SIGNAL DETECTION ONLY: do not sell, contact, qualify HOT/WARM/COLD, modify CRM or draft outreach. Use your configured web search tools actively. Never invent a signal, date or source. Return exactly one JSON object and no markdown or chain-of-thought.`;

const schema = `{
  \"signals\": [
    {
      \"signal_type\": \"one of: ${types.join('|')}\",
      \"signal_date\": \"YYYY-MM-DD|null\",
      \"source_url\": \"https://...\",
      \"source_title\": null,
      \"evidence_text\": \"short precise excerpt or paraphrase that supports this signal\",
      \"signal_strength\": 0.0,
      \"confidence\": 0.0
    }
  ],
  \"sources_checked\": [\"https://...\"],
  \"summary\": \"short auditable summary\"
}`;

const prompt = `Look for recent, evidenced commercial signals about this account, as of ${new Date().toISOString().slice(0,10)}.

ACCOUNT:
${JSON.stringify({id:account.id, name:account.name, website:account.website, region:account.region, commune:account.commune, city:account.city, phone:account.phone}, null, 2)}

WHAT TO LOOK FOR:
${guidance}

ALLOWED SIGNAL TYPES: ${types.join(', ')}

RULES:
1. A signal MUST have a real, checkable source_url and a short evidence_text quoting/paraphrasing what the source actually says.
2. A signal without a clear recent date should still be reported with signal_date=null, but prefer dated evidence.
3. signal_strength (0.0-1.0) reflects how strong/direct the evidence is, not how exciting the finding is.
4. If you find nothing real after a reasonable search, return an empty \"signals\" array. Do NOT invent a signal to avoid returning empty.
5. Use only the allowed signal types; if something relevant does not fit, omit it rather than mislabeling it.

RETURN EXACTLY ONE JSON OBJECT MATCHING THIS SCHEMA:
${schema}`;

return [{json:{account, system_prompt:system, user_prompt:prompt}}];

const cfg = $('Init Configuration').first().json;
const base = $('Build Signals Prompt').item.json;
const res = $input.first().json ?? {};
const status = Number(res.statusCode ?? 0);
const body = res.body ?? res;
const errors=[];
if (status<200||status>=300) errors.push(`OpenClaw HTTP ${status||'unknown'}`);
let content = body?.choices?.[0]?.message?.content;
if (typeof content !== 'string') errors.push('OpenClaw response missing choices[0].message.content');
let parsed=null;
if (typeof content==='string') {
  let cleaned=content.trim().replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/\s*```$/,'').trim();
  const first=cleaned.indexOf('{'), last=cleaned.lastIndexOf('}');
  if (first>=0 && last>first) cleaned=cleaned.slice(first,last+1);
  try { parsed=JSON.parse(cleaned); } catch(e) { errors.push(`Invalid JSON: ${e.message}`); }
}
if (!parsed || typeof parsed!=='object') parsed={};

const allowedTypes = new Set((cfg.signals_config && cfg.signals_config.types) || []);
const clamp=v=>{const n=Number(v);return Number.isFinite(n)?Math.max(0,Math.min(1,n)):null;};
const text=(v,max)=>typeof v==='string'&&v.trim()?v.trim().slice(0,max||2000):null;
const httpUrl=u=>{const s=text(u,2000); if(!s) return null; return /^https?:\/\/[^\s]+$/i.test(s)?s:null;};

const now = new Date().toISOString();
const signalRows=[];
for (const raw of (Array.isArray(parsed.signals)?parsed.signals:[])) {
  const source_url = httpUrl(raw && raw.source_url);
  const evidence_text = text(raw && raw.evidence_text,1800);
  if (!source_url || !evidence_text) continue;
  const signal_type = (raw && allowedTypes.has(raw.signal_type)) ? raw.signal_type : null;
  if (!signal_type) continue;
  const signal_date = /^\d{4}-\d{2}-\d{2}$/.test(String((raw&&raw.signal_date)||'')) ? String(raw.signal_date) : null;
  signalRows.push({
    account_id: base.account.id,
    icp_pack_id: 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46',
    signal_type,
    signal_date,
    signal_source: 'prospector/openclaw',
    signal_url: source_url,
    signal_evidence: evidence_text,
    signal_strength: clamp(raw.signal_strength) ?? clamp(raw.confidence) ?? 0.5,
    last_seen: now,
  });
}

return [{json:{
  account: base.account,
  valid: errors.length===0,
  parse_errors: errors,
  signal_rows: signalRows,
  summary: text(parsed.summary,2000),
  openclaw_http_status: status,
}}];

let s=null; try{s=$('Parse Signals Result').item.json;}catch{}
if(!s) return [{json:{account_id:null,error:'Could not recover signals state'}}];
return [{json:{
  account_id: s.account.id,
  account_name: s.account.name,
  signals_found: (s.signal_rows||[]).length,
  signal_types: (s.signal_rows||[]).map(r=>r.signal_type),
  valid: s.valid,
  parse_errors: s.parse_errors,
  summary: s.summary,
  workflow_revision: $('Init Configuration').first().json.workflow_revision,
}}];

const rows = $input.all().map(i => i.json);
const signalsFound = rows.reduce((sum,r)=>sum+Number(r.signals_found||0),0);
return [{json:{
  workflow:'02b - Signals Engine',
  revision: rows[0]?.workflow_revision || null,
  accounts_checked: rows.length,
  signals_found_total: signalsFound,
  results: rows,
}}];

// SEGURIDAD (2026-09-15): sin default de ICP pack.
const incoming = $input.first()?.json ?? {};
const icpPackId = incoming.icp_pack_id || null;
const icpPackSlug = incoming.icp_pack_slug || null;
if (!icpPackId && !icpPackSlug) {
  throw new Error('SEGURIDAD: icp_pack_id o icp_pack_slug es obligatorio (sin valor por defecto). Abortando.');
}
const filter = icpPackId ? `id=eq.${icpPackId}` : `slug=eq.${icpPackSlug}`;
return [{json:{
  limit: incoming.limit,
  account_ids: incoming.account_ids,
  icp_pack_url: `https://uwquwjmiofixzugttals.supabase.co/rest/v1/icp_packs?${filter}&select=id,slug,status,signals&limit=1`
}}];

const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const EXPECTED_ICP_PACK_SLUG = 'atacama-labs-test';
const row = $json;
if (!row || !row.icp_pack_id || !row.icp_pack_slug) throw new Error('SEGURIDAD: Parse ICP Pack no devolvio icp_pack_id/icp_pack_slug. Abortando.');
if (row.icp_pack_id !== EXPECTED_ICP_PACK_ID || row.icp_pack_slug !== EXPECTED_ICP_PACK_SLUG) {
  throw new Error(`SEGURIDAD: ICP pack resuelto (${row.icp_pack_slug} / ${row.icp_pack_id}) NO coincide con el esperado (${EXPECTED_ICP_PACK_SLUG} / ${EXPECTED_ICP_PACK_ID}). Abortando antes de leer o escribir nada.`);
}
return [{ json: { ...row, EXPECTED_ICP_PACK_ID, EXPECTED_ICP_PACK_SLUG } }];

const incoming = $input.first()?.json ?? {};
const icp = $('Assert Expected Pack').first().json;
const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const CONFIG = {
  supabase_url: 'https://uwquwjmiofixzugttals.supabase.co',
  openclaw_base_url: 'http://openclaw-gateway:18790',
  openclaw_model: 'openclaw/prospector',
  default_limit: 1,
  max_limit: 30,
  recheck_after_hours: 24,
  researcher: 'prospector/openclaw',
  workflow_revision: 'atacama-02b-signals-test-2026-09-15',
  icp_pack_id: EXPECTED_ICP_PACK_ID,
  icp_pack_slug: icp.icp_pack_slug,
  signals_config: icp.signals || {},
};

const requestedLimit = Number(incoming.limit ?? CONFIG.default_limit);
const limit = Number.isFinite(requestedLimit) ? Math.max(1, Math.min(CONFIG.max_limit, Math.trunc(requestedLimit))) : CONFIG.default_limit;

let accountIds = incoming.account_ids ?? [];
if (typeof accountIds === 'string') { try { accountIds = JSON.parse(accountIds); } catch { accountIds = accountIds.split(',').map(s=>s.trim()).filter(Boolean); } }
if (!Array.isArray(accountIds)) accountIds = [];
accountIds = [...new Set(accountIds.map(String).filter(Boolean))].slice(0, CONFIG.max_limit);

const cutoff = new Date(Date.now() - CONFIG.recheck_after_hours*3600*1000).toISOString();
const select = 'id,icp_pack_id,name,website,region,commune,city,phone';
const filters = [
  'research_status=eq.complete',
  `icp_pack_id=eq.${EXPECTED_ICP_PACK_ID}`,
  `or=(signals_checked_at.is.null,signals_checked_at.lt.${cutoff})`,
  `select=${select}`,
  'order=signals_checked_at.asc.nullsfirst',
  `limit=${limit}`,
];
if (accountIds.length) filters.push(`id=in.(${accountIds.join(',')})`);

return [{json: { ...CONFIG, request: { limit, account_ids: accountIds }, accounts_url: `${CONFIG.supabase_url}/rest/v1/accounts?${filters.join('&')}` }}];

const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const item = $json;
if (item.icp_pack_id !== EXPECTED_ICP_PACK_ID) {
  throw new Error(`SEGURIDAD: cuenta ${item.id} tiene icp_pack_id (${item.icp_pack_id}) distinto del esperado (${EXPECTED_ICP_PACK_ID}). Abortando antes de generar/escribir señales.`);
}
return { json: item };

const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const rows = $json.signal_rows || [];
if (rows.some(r => r.icp_pack_id !== EXPECTED_ICP_PACK_ID)) {
  throw new Error('SEGURIDAD: signal_rows contiene un icp_pack_id distinto del esperado. Abortando antes de escribir en signals.');
}
return $input.all();

const EXPECTED_ICP_PACK_ID = 'f412a742-7c7f-4cc0-9e2a-20c39d6fcd46';
const cfgId = $('Init Configuration').first().json.icp_pack_id;
if (cfgId !== EXPECTED_ICP_PACK_ID) throw new Error(`SEGURIDAD: icp_pack_id (${cfgId}) no coincide con el esperado (${EXPECTED_ICP_PACK_ID}) justo antes de actualizar accounts. Abortando.`);
return $input.all();
